namespace SysAdminAssistant.Core;
public static class NetworkIssueAdvice
{
    public static string Describe(NetworkProblem problem,NetworkRule? current=null,bool includeEvidence=true)
    {
        var saved=problem.Evidence.LastOrDefault();var rule=saved?.Rule??current;
        var steps=problem.RuleId switch{
            "connection"=>global::SysAdminAssistant.Core.ProductText.Get("Проверьте доступность адреса и порта API-SSL с сервера Assistant, маршрут, read-права учётной записи, время и сертификат RouterOS. ICMP-ответ не подтверждает работу API. Сверьте отпечаток независимо; не отключайте проверку TLS. После успешных опросов состояние восстановится автоматически."),
            "log-reader"=>global::SysAdminAssistant.Core.ProductText.Get("Проверьте read-права учётной записи на /log, доступность API, настройки журналирования и заполнение буфера RouterOS. Работа API ещё не подтверждает получение всех журналов; проверьте подробную ошибку опроса. Не очищайте буфер ради снятия предупреждения."),
            var id when id.StartsWith("flap-",StringComparison.Ordinal)=>global::SysAdminAssistant.Core.ProductText.Get("Интерфейс переключался вверх/вниз. Проверьте кабель/SFP, удалённый порт, ошибки интерфейса, питание и совпадение с плановыми работами. Даже если сейчас он поднят, повторяемость требует проверки. Закрытие зависит от периода стабильности правила."),
            "auth-failure-info" or "auth-failure-warning" or "auth-bruteforce"=>global::SysAdminAssistant.Core.ProductText.Get("Сверьте IP и учётную запись из исходного лога, проверьте старые пароли у служб мониторинга и разрешённые источники управления. Проверьте успешные входы рядом по времени. Неудачные попытки сами по себе не доказывают компрометацию."),
            "login-after-failures" or "management-login"=>global::SysAdminAssistant.Core.ProductText.Get("Сверьте источник и пользователя с администратором и плановыми работами. Неизвестный успешный вход после перебора требует расследования, сохранения журналов и проверки изменений конфигурации."),
            "configuration-change"=>global::SysAdminAssistant.Core.ProductText.Get("Откройте сохранённые исходные сообщения: кто, когда и какой объект менял. Сравните с согласованными работами и резервной конфигурацией. Событие изменения не означает, что вся конфигурация небезопасна."),
            "unexpected-reboot" or "reboot-storm"=>global::SysAdminAssistant.Core.ProductText.Get("Сверьте uptime, причину перезагрузки в RouterOS, питание/UPS, watchdog и обновления. При повторениях проверьте аппаратное состояние и нагрузку; текущая доступность не устанавливает причину прошлого сбоя."),
            "resource-failure"=>global::SysAdminAssistant.Core.ProductText.Get("Проверьте ресурсы, свободное место, состояние накопителя и точную ошибку ядра/памяти. Сохраните журналы и резервную конфигурацию. Не форматируйте накопитель и не сбрасывай роутер по одному сообщению."),
            "power-temperature"=>global::SysAdminAssistant.Core.ProductText.Get("Сверьте датчики температуры, питание, вентиляторы и условия охлаждения с допустимыми значениями модели. Проверьте физическое состояние и питание; не маскируй проблему отключением контроля."),
            "storage-warning"=>global::SysAdminAssistant.Core.ProductText.Get("Проверьте свободное место и состав файлов RouterOS. Определи назначение файлов и резервных копий перед очисткой; не удаляйте пакеты или неизвестные системные файлы."),
            "certificate-warning"=>global::SysAdminAssistant.Core.ProductText.Get("Сверьте время, имя узла, срок сертификата и отпечаток с независимым доверенным источником. Проверьте CA и сертификат службы. Не отключайте проверку TLS и не принимайте случайный отпечаток ради снятия ошибки."),
            "syn-flood"=>global::SysAdminAssistant.Core.ProductText.Get("Сверьте источники и скорость запросов, загрузку CPU/канала и счётчики firewall. Проверьте, не является ли это ожидаемым трафиком. Ограничения вводите после проверки полного пути пакета, сохранив административный доступ."),
            "router-critical"=>global::SysAdminAssistant.Core.ProductText.Get("Откройте точный текст и темы RouterOS, сопоставь с недавними работами и соседними событиями. Категория critical не устанавливает конкретную причину; нужны исходные данные."),
            _=>problem.Kind=="Log"?global::SysAdminAssistant.Core.ProductText.Get("Для пользовательского правила проверьте исходное сообщение, совпавшие условия, порог и группировку. Причина не выводится из названия правила. Проверьте назначение события перед изменениями."):rule?.Role=="Tunnel"?global::SysAdminAssistant.Core.ProductText.Get("Проверьте доступность удалённого конца и WAN, состояние/логи туннеля с обеих сторон, время, сертификаты и параметры согласования. Не перезапускайте все VPN и не меняйте firewall без проверки причины."):global::SysAdminAssistant.Core.ProductText.Get("Проверьте состояние и комментарий указанного интерфейса, кабель/SFP, удалённый порт и питание. Для WAN проверьте шлюз/провайдера; при частых переключениях — ошибки порта, физику и совпадение с работами. Отсутствие опроса и реальный link down — разные причины.")};
        var facts=global::SysAdminAssistant.Core.ProductText.Get($"Последнее событие: {problem.LastSeen.ToServerTime():dd.MM.yyyy HH:mm:ss}; повторов: {problem.Repeats}.");
        if(saved!=null)facts+=global::SysAdminAssistant.Core.ProductText.Get($" При срабатывании совпадений в окне: {saved.MatchedCount}; оценено {saved.EvaluatedAtUtc.ToServerTime():dd.MM.yyyy HH:mm:ss}.");
        if(rule!=null)facts+=rule.Kind=="Log"?global::SysAdminAssistant.Core.ProductText.Get($" Правило {rule.Name}; порог {rule.Threshold} за {rule.WindowSeconds} с."):global::SysAdminAssistant.Core.ProductText.Get($" Правило {rule.Name}; роль {rule.Role}, задержка {rule.DelaySeconds} с, восстановление после {rule.RecoveryChecks} успешных проверок.");
        var close=problem.Kind!="Log"?global::SysAdminAssistant.Core.ProductText.Get("Закрывается после подтверждённого восстановления опросом."):rule?.AutoCloseSeconds>0?global::SysAdminAssistant.Core.ProductText.Get($"Закрывается после {rule.AutoCloseSeconds} с без повторов при работающем сборе; новый повтор начинает отсчёт заново."):global::SysAdminAssistant.Core.ProductText.Get("Требует ручного подтверждения после разбора причины.");
        return facts+global::SysAdminAssistant.Core.ProductText.Get("\nЧто проверить и как устранить: ")+steps+global::SysAdminAssistant.Core.ProductText.Get("\nЗакрытие: ")+close+(!includeEvidence?"":saved==null?global::SysAdminAssistant.Core.ProductText.Get("\nИсходная запись для этого состояния не сохранена; не восстанавливай причину догадкой."):global::SysAdminAssistant.Core.ProductText.Get("\nИсходное сообщение: ")+saved.Log.Message);
    }
}
